const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '数轴：标出 1/2 与 2/3' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1/6' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '2/3' },
      { kind: 'text', payload: '5/6' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '从小到大：1/2 < 2/3' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.10;
    var x1 = W * 0.90;
    var y = H * 0.58;
    var step = (x1 - x0) / 6;
    function tx(k) { return x0 + k * step; }

    var axisPath = visualSdk.axis({ x0: x0, y0: y, x1: x1, y1: y, ticks: 6, tickLength: 14 });
    var dotHalf = visualSdk.circle(tx(3), y, 9);
    var dotTwoThirds = visualSdk.circle(tx(4), y, 9);

    var tickPos = [0, 1, 2, 5, 6];
    var tickText = [1, 2, 3, 6, 7];

    var children = [
      { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'dotHalf', fill: '#c0392b' },
      { type: 'path', pathId: 'dotTwoThirds', fill: '#1f6fb2' },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: H * 0.14 },
        hAlign: 'center', vAlign: 'middle', color: '#26354a' }
    ];

    for (var i = 0; i < tickPos.length; i++) {
      children.push({ type: 'label', contentId: metrics[tickText[i]].contentId,
        anchor: { x: tx(tickPos[i]), y: y + 22 }, hAlign: 'center', vAlign: 'top', color: '#26354a' });
    }

    children.push({ type: 'label', contentId: metrics[4].contentId,
      anchor: { x: tx(3), y: y - 26 }, hAlign: 'center', vAlign: 'bottom', color: '#c0392b' });
    children.push({ type: 'label', contentId: metrics[5].contentId,
      anchor: { x: tx(4), y: y - 26 }, hAlign: 'center', vAlign: 'bottom', color: '#1f6fb2' });
    children.push({ type: 'label', contentId: metrics[8].contentId,
      anchor: { x: W / 2, y: H * 0.86 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' });

    return {
      schemaVersion: 1,
      sceneId: 'fraction-numberline',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axisPath },
        { id: 'dotHalf', commands: dotHalf },
        { id: 'dotTwoThirds', commands: dotTwoThirds }
      ],
      root: { type: 'group', children: children }
    };
  }
};
